+	}
+
+	private clear(): void {
+		this.cached = null;
+		try {
+			rmSync(this.filePath, { force: true });
+		} catch {}
+	}
+
+	private readFile(): PersistedSessionState | undefined {
+		const parsed = readJsonFile(this.filePath) as
+			| Partial<PersistedSessionState>
+			| null
+			| undefined;
+		return parsed?.v === SESSION_STATE_VERSION &&
